class Solution {
public:
    struct Item {
        long long value;
        long long wt;

        Item(long long v, long long w) {
            value = v;
            wt = w;
        }
    };

    static bool comp(const Item& a, const Item& b) {
        double r1 = (double)a.value / a.wt;
        double r2 = (double)b.value / b.wt;
        return r1 > r2;
    }

    double fractionalKnapsack(vector<long long>& val,
                              vector<long long>& wt,
                              long long capacity) {

        int n = val.size();
        vector<Item> arr;

        for (int i = 0; i < n; i++) {
            arr.emplace_back(val[i], wt[i]);
        }

        // Sort by value/weight ratio in descending order
        sort(arr.begin(), arr.end(), comp);

        long long curwt = 0;
        double finalvalue = 0.0;

        for (int i = 0; i < n; i++) {

            // Take the whole item
            if (curwt + arr[i].wt <= capacity) {
                curwt += arr[i].wt;
                finalvalue += arr[i].value;
            }
            // Take only the fraction that fits
            else {
                long long remain = capacity - curwt;
                finalvalue += ((double)arr[i].value / arr[i].wt) * remain;
                break;
            }
        }

        return finalvalue;
    }
};

